INSIDE_FUNCTION ! { #[doc = " A macro's expansion does not fit in this fragment kind."] #[doc = " For example, a non-type macro in a type position."] fn error_wrong_fragment_kind (& mut self , kind : AstFragmentKind , mac : & ast :: MacCall , span : Span ,) -> ErrorGuaranteed { let guar = self . cx . dcx () . emit_err (WrongFragmentKind { span , kind : kind . name () , name : & mac . path }) ; self . cx . macro_error_and_trace_macros_diag () ; guar}
}